// Lead r6 (2026-11-17): ONE moving-gameplay audit method for every playable screen 04–08 (read-only).
// From the screen's approved-view checkpoint it rides the real game simulation forward / steers and screenshots what
// the live camera sees, so every screen is judged with the same shots. Generalises tools/match08/motion08.mjs.
// Run from the checkout to test (vite serves the current directory):
//   node <path>/motion_audit.mjs <screen 04..08> <outDir> [query]
import { mkdirSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const { loadPlaywright, CHROMIUM_ARGS, startVite } = await import(pathToFileURL(`${process.cwd()}/scripts/lib/pw.mjs`).href);
const [SCREEN, OUT, Q = ''] = process.argv.slice(2);
mkdirSync(OUT, { recursive: true });
const { chromium } = loadPlaywright();
const vite = await startVite(5270 + Number(SCREEN));
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
const log = [];
// [name, forward distance in world units from the checkpoint (or 'tN' = fraction N of the rest of the stage), steer]
const SHOTS = [
  ['a00_approved_view', 0, null],
  ['f03_forward3u', 3, null], ['f06_forward6u', 6, null], ['f10_forward10u', 10, null], ['f20_forward20u', 20, null],
  ['s_left_steer', 6, -1], ['s_right_steer', 6, 1], ['s_left_hard', 12, -1], ['s_right_hard', 12, 1],
  ['t33_through_screen', 't0.33', null], ['t66_through_screen', 't0.66', null], ['t95_through_screen', 't0.95', null],
];
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  page.on('pageerror', (e) => console.error('pageerror', e.message));
  await page.goto(`${vite.url}/?qa=1&dpr=1${Q ? '&' + Q : ''}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
  for (const [name, dist, steer] of SHOTS) {
    const st = await page.evaluate(async ([id, dist, steer]) => {
      const r = window.__rainbow; r.goto(id);
      const s0 = r.state().s;
      const stg = r.course.stage(id);
      const s1 = stg.s1 ?? (stg.s0 + (stg.length ?? 0));
      const target = typeof dist === 'string' ? s0 + Number(dist.slice(1)) * Math.max(0, s1 - s0) : s0 + dist;
      r.setSteer(steer);
      let n = 0; while (r.state().s < target - 1e-3 && n < 4000) { r.step(1); n++; }
      r.setSteer(null);
      r.run(true); await new Promise((res) => requestAnimationFrame(() => requestAnimationFrame(res))); r.run(false);
      return { ...r.state(), frames: n, s0, s1, target };
    }, [SCREEN, dist, steer]);
    await page.waitForTimeout(150);
    await page.screenshot({ path: `${OUT}/${name}.png` });
    log.push({ name, dist, steer, ...st });
    console.log(SCREEN, name, 's', st.s, 'lat', st.lat, 'stage', st.stage, 'frames', st.frames);
  }
} finally {
  writeFileSync(`${OUT}/motion.json`, JSON.stringify({ screen: SCREEN, query: Q, shots: log }, null, 1));
  await browser.close(); await vite.close?.();
}

#!/usr/bin/env node
// Lead r13 (2026-11-18): a short REAL-GAMEPLAY swimming clip for any playable screen 04–08 (read-only).
// Starts at the screen's checkpoint and rides the real game simulation (Benny, camera rig, course, coins unchanged) with
// the shader clock running: straight, then left, then right, then straight — one frame per 1/fps s → OUT/0000.png …
// Generalises scripts/proj05-move.mjs --zigzag. Encode: ffmpeg -framerate 24 -i OUT/%04d.png -pix_fmt yuv420p clip.mp4
//   node tools/lead_r13/swim_clip.mjs <screen 04..08> <outDir> <seconds> [query]
import { mkdirSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const { loadPlaywright, CHROMIUM_ARGS, startVite } = await import(pathToFileURL(`${process.cwd()}/scripts/lib/pw.mjs`).href);
const [SCREEN, OUT, SECS = '6', Q = ''] = process.argv.slice(2);
const fps = 24;
mkdirSync(OUT, { recursive: true });
const { chromium } = loadPlaywright();
const vite = await startVite(5280 + Number(SCREEN));
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  page.on('pageerror', (e) => console.error('pageerror', e.message));
  await page.goto(`${vite.url}/?qa=1&dpr=1${Q ? '&' + Q : ''}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
  await page.evaluate((id) => window.__rainbow.goto(id), SCREEN);
  const n = Math.round(Number(SECS) * fps);
  for (let i = 0; i < n; i++) {
    const ph = i / n;                                   // straight 0–0.3, left 0.3–0.55, right 0.55–0.8, straight
    const dir = ph < 0.3 ? null : ph < 0.55 ? -1 : ph < 0.8 ? 1 : null;
    await page.evaluate(([t, dt, dir]) => { const R = window.__rainbow; R.setSteer(dir); R.freezeAt(t); R.step(Math.round(dt * 60), 1 / 60); R.freezeAt(t + dt); R.step(1, 1e-4); }, [12 + i / fps, 1 / fps, dir]);
    await page.evaluate(() => window.__rainbow.drawList());
    await page.screenshot({ path: `${OUT}/${String(i).padStart(4, '0')}.png` });
  }
  console.log('frames', n);
} finally {
  await browser.close();
  await vite.close();
}
// r7 (2026-11-18): checkpoint captures for 0-px proofs (default build and switch sets). Run from the checkout to test.
// usage: node <path>/proof0px_r7.mjs <outDir> <port> [query]
import { mkdirSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const { loadPlaywright, CHROMIUM_ARGS, startVite } = await import(pathToFileURL(`${process.cwd()}/scripts/lib/pw.mjs`).href);
const [OUT, PORT = '5301', Q = ''] = process.argv.slice(2);
mkdirSync(OUT, { recursive: true });
const IDS = ['06', '07', '07a_plunge_top', '07b_plunge_mid', '07c_plunge_bottom', '07d_entering_08', '08'];
const { chromium } = loadPlaywright(); const vite = await startVite(Number(PORT));
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  await page.goto(`${vite.url}/?qa=1&dpr=1${Q ? '&' + Q : ''}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
  for (const id of IDS) {
    await page.evaluate((id) => window.__rainbow.goto(id), id); // deterministic: frozen clock, rendered once
    await page.waitForTimeout(150);
    await page.screenshot({ path: `${OUT}/${id}.png` });
  }
} finally { await browser.close(); await vite.close?.(); }

#!/usr/bin/env node
// Playwright capture of the REAL running game (WebGL) at the native reference sizes.
//   node scripts/capture.mjs                 → screenshots/01.png … 11.png (+ qa/capture_log.json)
//   node scripts/capture.mjs 03 07           → only those
//   node scripts/capture.mjs --plunge        → qa/continuity/07a…07d.png descent proof frames
//   node scripts/capture.mjs --size=1080x1920 → extra Android-size set into screenshots/1080x1920/
//   node scripts/capture.mjs --out=DIR       → custom output dir
import { mkdirSync, writeFileSync } from 'node:fs';
import { loadPlaywright, CHROMIUM_ARGS, startVite } from './lib/pw.mjs';

const args = process.argv.slice(2);
const opt = Object.fromEntries(args.filter((a) => a.startsWith('--')).map((a) => { const [k, ...r] = a.slice(2).split('='); return [k, r.length ? r.join('=') : true]; }));
let ids = args.filter((a) => !a.startsWith('--'));
const NATIVE = { '03': [727, 1536] };
const plunge = ['07a_plunge_top', '07b_plunge_mid', '07c_plunge_bottom', '07d_entering_08'];
if (opt.plunge) ids = plunge;
if (!ids.length) ids = ['01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11'];
const size = typeof opt.size === 'string' ? opt.size.split('x').map(Number) : null;
const outDir = typeof opt.out === 'string' ? opt.out : opt.plunge ? 'qa/continuity' : size ? `screenshots/${size[0]}x${size[1]}` : 'screenshots';
mkdirSync(outDir, { recursive: true });
mkdirSync('qa', { recursive: true });

const { chromium } = loadPlaywright();
const vite = await startVite(5201);
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
const log = { when: new Date().toISOString(), renderer: null, shots: [], errors: [] };
try {
  for (const id of ids) {
    const [w, h] = size ?? NATIVE[id] ?? [864, 1536];
    const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
    page.on('console', (m) => { if (m.type() === 'error') log.errors.push(`[${id}] ${m.text()}`); });
    page.on('pageerror', (e) => log.errors.push(`[${id}] pageerror ${e.message}`));
    await page.goto(`${vite.url}/?qa=1&dpr=1${typeof opt.q === "string" ? "&" + opt.q : ""}`);
    await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 240000 });
    const err = await page.evaluate(() => window.__error);
    if (err) throw new Error(err);
    if (!log.renderer) log.renderer = await page.evaluate(() => { const g = document.querySelector('canvas').getContext('webgl2'); const d = g?.getExtension('WEBGL_debug_renderer_info'); return d ? g.getParameter(d.UNMASKED_RENDERER_WEBGL) : 'unknown'; });
    const st = await page.evaluate((cid) => window.__rainbow.goto(cid), id);
    // let a few frames render (fonts, bloom) — time is frozen so the image is deterministic
    await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => r())));
    await page.evaluate(() => document.fonts.ready);
    await page.waitForTimeout(250);
    const name = /^\d\d$/.test(id) ? `${id}.png` : `${id}.png`;
    await page.screenshot({ path: `${outDir}/${name}`, timeout: 180000 });
    const stats = await page.evaluate(() => window.__rainbow.stats());
    // The first frame after load also counts one-time GPU work (three converts each cube env map to PMREM on
    // first use). Render once more (after the screenshot) and report that per-frame cost as calls/tris.
    const firstFrame = { calls: stats.calls, triangles: stats.triangles };
    await page.evaluate(() => window.__rainbow.drawList?.());
    const steady = await page.evaluate(() => window.__rainbow.stats());
    Object.assign(stats, { calls: steady.calls, triangles: steady.triangles, firstFrameCalls: firstFrame.calls, firstFrameTriangles: firstFrame.triangles });
    const state = await page.evaluate(() => window.__rainbow.state());
    log.shots.push({ id, file: `${outDir}/${name}`, size: [w, h], checkpoint: st, state, stats });
    console.log(id, '→', `${outDir}/${name}`, JSON.stringify({ stage: state.stage, s: state.s, y: state.bennyY, calls: stats.calls, tris: stats.triangles, modules: stats.modules }));
    await page.close();
  }
} finally {
  writeFileSync(opt.plunge ? 'qa/continuity/capture_log.json' : `qa/capture_log${size ? '_' + size.join('x') : ''}.json`, JSON.stringify(log, null, 2));
  await browser.close();
  await vite.close();
#!/usr/bin/env node
// Automated gameplay + continuity test on the REAL running game (headless Chromium, WebGL).
// Drives Benny from 03 to the 11 ending with the deterministic simulation API and checks:
//  * continuous travel: s strictly increases, no position jump > speed·dt (no teleport/cut)
//  * camera continuity: no camera jump between steps (no hard cut), incl. the 07 plunge → 08
//  * 07 plunge: positive travel time, large vertical drop, 08 inlet reached from the bottom
//  * real coin pickups update the counter; steering into the foam wall costs a heart
//  * pause freezes the simulation; resume continues
//  * the run ends in the 11 victory with Benny hidden under the towel
// Writes qa/gameplay_test.json and qa/07_to_08_continuity.md. Exit 1 on failure.
//   node scripts/gameplay-test.mjs --q=river05=1 --out=qa/pilot05/wave11/tests/gameplay_river05.json
//   → the same run with URL test switches; with --q the tracked qa/ files above are NOT rewritten.
import { writeFileSync, mkdirSync } from 'node:fs';
import { loadPlaywright, CHROMIUM_ARGS, startVite } from './lib/pw.mjs';

const optQ = (process.argv.find((a) => a.startsWith('--q=')) ?? '').slice(4);
const optOut = (process.argv.find((a) => a.startsWith('--out=')) ?? '').slice(6);
mkdirSync('qa', { recursive: true });
const { chromium } = loadPlaywright();
const vite = await startVite(5213);
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
const page = await browser.newPage({ viewport: { width: 216, height: 384 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
await page.goto(`${vite.url}/?qa=1&dpr=1&bloom=0${optQ ? '&' + optQ : ''}`);
await page.waitForFunction(() => window.__rainbow?.ready, null, { timeout: 240000 });

const result = await page.evaluate(() => {
  const api = window.__rainbow;
  const c = api.course;
  const dt = 1 / 60;
  const out = { checks: {}, samples: [], plunge: {} };
  // ---- pause / resume
  api.startRideAt('03');
  api.setSteer(0);
  api.step(30, dt);
  const sBefore = api.state().s;
  api.togglePause();
  api.step(60, dt);
  const sPaused = api.state().s;

// Resolve the Playwright that is pre-installed in this environment (global node_modules),
// falling back to a local install. Chromium launch flags give WebGL2 via SwiftShader headless.
import { createRequire } from 'node:module';
import { execSync } from 'node:child_process';
import { join } from 'node:path';

export function loadPlaywright() {
  try {
    return createRequire(import.meta.url)('playwright');
  } catch {
    const root = execSync('npm root -g').toString().trim();
    return createRequire(join(root, 'noop.js'))('playwright');
  }
}

export const CHROMIUM_ARGS = ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'];

/** start a Vite dev server for the project and return { url, close } */
export async function startVite(port = 5199) {
  const { createServer } = await import('vite');
  const server = await createServer({ server: { port, strictPort: false, host: '127.0.0.1', hmr: false, watch: { ignored: ['**/*'] } }, logLevel: 'error' });
  await server.listen();
  const addr = server.resolvedUrls?.local?.[0] ?? `http://127.0.0.1:${port}/`;
  return { url: addr.replace(/\/$/, ''), close: () => server.close() };
}

export async function waitDone(page, timeoutMs = 180000) {
  await page.waitForFunction(() => window.__done === true, null, { timeout: timeoutMs });
  const err = await page.evaluate(() => window.__error);
  if (err) throw new Error(err);
}
